import React, { Component } from "react";
import { Card, CardBody, CardHeader, Col, Row, Table, Button, CustomInput, CardGroup } from "reactstrap";
import { connect } from "react-redux";
// import Pagination2 from "react-js-pagination";
import Loader from "react-loader-spinner";
// import Widget04 from './Widgets04';
import Widget05 from "../../../../Utils/Widgets05";

import {
	fetchVisaIssuerSummary,
	fetchVisaIssuerSummaryStats,
	downloadVisaIssuerCsvSummary,
	downloadAutomaticVisaIssuerCsvSummary,
} from "../../../../actions/filesets";

import { FormattedMessage } from "react-intl";

// components
import PostingTable from "../../../../components/PostingTable";
import PostingTableHeader from "../../../../components/PostingTableHeader";

class UnvalidatedEntries extends Component {
	constructor (props) {
		super(props);
		this.state = {
			activePage     : 1,
			userAffiliates : localStorage.getItem("userAffilliates"),
			isChecked      : true,
			downloadFormat : false,
		};
	}

	componentDidMount () {
		this.props.fetchVisaIssuerSummary(this.props.match.params.date);
		this.props.fetchVisaIssuerSummaryStats(this.props.match.params.date);
	}

	componentDidUpdate (prevProps) {
		if (this.props.selectedAffiliateCode !== prevProps.selectedAffiliateCode) {
			this.props.fetchVisaIssuerSummary(this.props.match.params.date);
			this.props.fetchVisaIssuerSummaryStats(this.props.match.params.date);
		}

		if (this.props.match.params.date !== prevProps.match.params.date) {
			this.props.fetchVisaIssuerSummary(this.props.match.params.date);
			this.props.fetchVisaIssuerSummaryStats(this.props.match.params.date);
		}
	}

	handleChangeDownloadFormat = () => {
		// handles which format is download if true Automatic, if false Manual
		this.setState({ isChecked: !this.state.isChecked, downloadFormat: !this.state.downloadFormat });
	};

	handleDownloadVisaPostingCsv = () => {
		this.setState({ isLoading: true });

		if (this.state.downloadFormat === false) {
			// this boolean values are working in opposite format for strange reasonse
			this.props.downloadAutomaticVisaIssuerCsvSummary(this.props.match.params.date);
		}

		if (this.state.downloadFormat === true) {
			// this boolean values are working in opposite format for strange reasonse
			this.props.downloadVisaIssuerCsvSummary(this.props.match.params.date);
		}
	};

	render () {
		let affiliateHTML = "";
		const userAffiliates = JSON.parse(localStorage.getItem("userAffilliates"));
		const selectedAffiliate = localStorage.getItem("selectedAfilliate");
		if (selectedAffiliate && userAffiliates) {
			affiliateHTML = userAffiliates.find((item) => item.code === selectedAffiliate).htmlCurrencyCode;
		}
		return (
			<div className='animated fadeIn'>
				{this.props.visaIssuerSummaryStats ? (
					<Row>
						<Col>
							<CardGroup className='mb-4'>
								<Widget05
									icon='icon-people'
									color='info'
									header={Math.abs(
										this.props.visaIssuerSummaryStats.data.settlementAmount,
									).toLocaleString()}
									value='25'
									currencycode={affiliateHTML}
								>
									AMOUNT
								</Widget05>
								<Widget05
									icon='icon-user-follow'
									color='success'
									header={this.props.visaIssuerSummaryStats.data.creditCount.toLocaleString()}
									value='25'
								>
									CREDITS
								</Widget05>
								<Widget05
									icon='icon-basket-loaded'
									color='warning'
									header={this.props.visaIssuerSummaryStats.data.debitCount.toLocaleString()}
									value='25'
								>
									DEBITS
								</Widget05>
								<Widget05
									icon='icon-pie-chart'
									color='primary'
									header={Math.abs(
										this.props.visaIssuerSummaryStats.data.settlementAmount,
									).toLocaleString()}
									value='25'
									currencycode={affiliateHTML}
								>
									CONTROL AMOUNT
								</Widget05>
								{/* <Widget04 icon="icon-speedometer" color="danger" header="5:34:11" value="25">Avg. Time</Widget04> */}
							</CardGroup>
						</Col>
					</Row>
				) : (
					""
				)}
				<Row>
					<Col lg={12}>
						<Card>
							<CardHeader className='d-flex justify-content-between align-items-center'>
								<strong>Visa Issuer {this.props.match.params.date} Summary</strong>
								<div className='card-header-actions'>
									{this.props.visaIssuerSummary && (
										<article className='d-flex justify-content-between align-items-center w-100'>
											<CustomInput
												className='mx-1'
												type='radio'
												id='exampleCustomRadio3'
												label='Automatic'
												htmlFor='exampleCustomRadio4_X'
												checked={this.state.isChecked}
												onChange={this.handleChangeDownloadFormat}
											/>

											<CustomInput
												className='mx-1'
												type='radio'
												id='exampleCustomRadio4'
												label='Manual'
												htmlFor='exampleCustomRadio4_X'
												checked={!this.state.isChecked}
												onChange={this.handleChangeDownloadFormat}
											/>

											<Button
												type='button'
												className={"float-right mb-0 btn-sm mx-1"}
												onClick={this.handleDownloadVisaPostingCsv}
												color={"success"}
												download={"" + 1 + ".csv"}
											>
												<span
													className={"d-flex px-2 justify-content-center align-items-center"}
												>
													<i className='fa fa-download' />&nbsp;
													{this.props.download_status && (
														<Loader
															type='ThreeDots'
															color='#FFF'
															height={30}
															width={30}
															style={{ textAlign: "center" }}
														/>
													)}
													{!this.props.download_status && (
														<FormattedMessage
															id='Download CSV'
															defaultMessage='Download CSV'
														/>
													)}
												</span>
											</Button>
										</article>
									)}
								</div>
							</CardHeader>

							<CardBody>
								{/* Handle Loading */}
								{!this.props.visaIssuerSummary &&
								!this.props.visaIssuerSummaryError && (
									<article className='d-flex justify-content-center align-items-center'>
										<div>
											<Loader type='ThreeDots' color='#00BFFF' height={100} width={100} />
										</div>
									</article>
								)}

								{/* Handle Error */}
								{!this.props.visaIssuerSummary &&
								this.props.visaIssuerSummaryError && (
									<article className='d-flex justify-content-center align-items-center'>
										<p className='text-center text-danger'>
											<FormattedMessage
												id={this.props.visaIssuerSummaryError.data.message}
												defaultMessage={this.props.visaIssuerSummaryError.data.message}
											/>
										</p>
									</article>
								)}

								{/* Handle 404 Not found */}
								{this.props.visaIssuerSummary &&
								this.props.visaIssuerSummary.data &&
								this.props.visaIssuerSummary.data.length === 0 && (
									<article className='d-flex justify-content-center align-items-center'>
										<p className='text-center text-danger'>
											<FormattedMessage
												id='There are no fileset batches summary at the moment.'
												defaultMessage='There are no fileset batches summary at the moment.'
											/>
										</p>
									</article>
								)}

								{/* Handle display content */}
								{this.props.visaIssuerSummary && (
									<Table hover bordered striped responsive size='sm' style={{ minWidth: "180%" }}>
										<thead>
											<PostingTableHeader />
										</thead>
										<tbody>
											<PostingTable dataRecords={[ ...this.props.visaIssuerSummary.data ]} />
										</tbody>
									</Table>
								)}
								{/* {this.props.fileSetBatchesPaginated?<nav>
                    <Pagination2
                        activePage={this.state.activePage}
                        itemsCountPerPage={20}
                        totalItemsCount={this.props.fileSetBatchesPaginated?this.props.fileSetBatchesPaginated.meta.totalElements:null}
                        pageRangeDisplayed={5} 
                        onChange={this.handlePageChange}
                    />
                    </nav>:'' } */}
							</CardBody>
						</Card>
					</Col>
				</Row>
			</div>
		);
	}
}

const mapStateToProps = (state) => {
	return {
		download_status        : state.fileSets.download_status,
		visaIssuerSummary      : state.fileSets.visaIssuerSummary,
		visaIssuerSummaryError : state.fileSets.visaIssuerSummaryError,
		visaIssuerSummaryStats : state.fileSets.visaIssuerSummaryStats,
		selectedAffiliateCode  : state.fileSets.selectedAffiliateCode,
		utils                  : state.utils,
	};
};

export default connect(mapStateToProps, {
	fetchVisaIssuerSummary,
	fetchVisaIssuerSummaryStats,
	downloadVisaIssuerCsvSummary,
	downloadAutomaticVisaIssuerCsvSummary,
})(UnvalidatedEntries);
